window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8ba88db5c3893244"]={"versions": [{"id": "FIG-8ba88db5c3893244", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm mit bedingter Verzweigung (<code>alt</code>-Fragment).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses bei der Meldung eines Überwachungspunktes (<em>Checkpoint</em>) durch eine Applikation an das Laufzeitüberwachungssystem unter Einbeziehung von Zugriffsvalidierung und sicherheitsrelevanter Anomalieerfassung.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (AP R23-11), Zusammenspiel des funktionalen Sicherheitsclusters <em>Platform Health Management</em> (PHM) mit dem Security-Cluster <em>Intrusion Detection System Manager</em> (IdsM) sowie einer instanziierten <em>Adaptive Application</em>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>:Adaptive Application</code>: Prozessinstanz im User-Space, instrumentiert mit Checkpoints zur Kontrollfluss- und Lebendigkeitsüberwachung.</li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code>: Zentraler Systemdienst zur Überwachung von <em>Alive-</em>, <em>Deadline-</em> und <em>Logical Supervisions</em>.</li>\n<li><code>«aapFunctionalCluster» :Intrusion Detection System Manager</code>: Zentraler Plattformdienst zur Erfassung, Filterung und Weiterleitung von Security-Ereignissen (<em>Security Events</em>).</li>\n<li><strong>Operationen & Schnittstellen:</strong></li>\n<li><code>ReportCheckpoint()</code>: Interaktionsaufruf (IPC/API, i. d. R. <code>ara::phm</code>) von der Applikation an das PHM mit Übergabe der Checkpoint-ID.</li>\n<li><code>checkAccess()</code>: PHM-interner Validierungsaufruf zur Prüfung der Prozess-Identität und Sendeberechtigung gegen die hinterlegte Zugriffs- bzw. Sicherheitskonfiguration (Identity & Access Management).</li>\n<li><code>handleReportedCheckpoint()</code>: PHM-interne Routine zur Aktualisierung der Überwachungsmodi (z. B. Hochzählen von Alive-Countern, Timer-Stopp/Start bei Deadlines, Graph-Traversierung bei Logical Supervisions).</li>\n<li><code>ReportEvent()</code>: Standardisierte API-Interaktion (<code>ara::idsm</code>) zur Übergabe eines definierten Security Events (SEv) an den IdsM bei unautorisiertem Zugriff.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Die <code>:Adaptive Application</code> erreicht im Kontrollfluss einen Messpunkt und ruft synchron/asynchron <code>ReportCheckpoint()</code> auf dem <code>:Platform Health Management</code> auf.</li>\n<li><strong>Autorisierungsprüfung:</strong> PHM führt unverzüglich die interne Routine <code>checkAccess()</code> aus, um zu verifizieren, ob der aufrufende Kontext (Prozess/UID/PID) für diese spezifische Checkpoint-ID autorisiert ist.</li>\n<li><strong>Bedingte Verzweigung (<code>alt</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>[access granted]</code>:</strong> Bei erfolgreicher Autorisierung ruft PHM intern <code>handleReportedCheckpoint()</code> auf. Der Status der zugeordneten Supervisions (Alive/Deadline/Logical) wird aktualisiert; keine Benachrichtigung externer Security-Cluster.</li>\n<li><strong>Pfad <code>[access denied]</code>:</strong> Ist der Prozess nicht autorisiert (z. B. Prozess-Spoofing, korrumpierter Kontext), bricht PHM die Checkpoint-Auswertung ab und meldet den Vorfall via <code>ReportEvent()</code> an den <code>:Intrusion Detection System Manager</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest- & Konfigurationspflichten:</strong></li>\n<li>Checkpoints müssen im ARXML-Datenmodell (<code>HealthChannelAction</code>, <code>SupervisedEntity</code>, <code>Checkpoint</code>) modelliert und eindeutig einer Applikation bzw. einem Executable zugeordnet sein.</li>\n<li>Berechtigungen müssen in den Zugriffsregeln (IAM/Security Profiles) des PHM gepflegt sein; Diskrepanzen zwischen Applikationscode und Manifest führen unmittelbar zu <code>access denied</code>.</li>\n<li><strong>Einfluss auf die Applikationsentwicklung:</strong></li>\n<li>Applikationen dürfen Checkpoint-IDs nicht generisch oder dynamisch wählen; unzulässige oder nicht zugeordnete IDs provozieren Security-Meldungen im System.</li>\n<li>Instrumentierung mit <code>ReportCheckpoint()</code> muss strikt deterministisch erfolgen, um Timing- und Kontrollflussfehler zu vermeiden.</li>\n<li><strong>Einfluss auf Plattform-/Stack-Entwickler:</strong></li>\n<li>Das PHM muss eine performante Prozessauthentifizierung bereitstellen (z. B. via Peer-Credentials über Unix Domain Sockets), damit <code>checkAccess()</code> minimalen Overhead auf die Echtzeitausführung hat.</li>\n<li>Für den IdsM muss eine dedizierte <em>Security Event Definition</em> (SEv) für fehlgeschlagene Checkpoint-Zugriffe parametriert sein, inklusive Context-Data-Payload (z. B. fehlerhafte ID, anfragende Prozess-ID).</li>\n</ul>"}, {"id": "FIG-0aaa2ebc8b17d424", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm mit bedingter Verzweigung (<code>alt</code>-Fragment).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses bei der Meldung eines Überwachungspunktes (<em>Checkpoint</em>) durch eine Applikation an das Laufzeitüberwachungssystem unter Einbeziehung von Zugriffsvalidierung und sicherheitsrelevanter Anomalieerfassung.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (AP R23-11), Zusammenspiel des funktionalen Sicherheitsclusters <em>Platform Health Management</em> (PHM) mit dem Security-Cluster <em>Intrusion Detection System Manager</em> (IdsM) sowie einer instanziierten <em>Adaptive Application</em>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>:Adaptive Application</code>: Prozessinstanz im User-Space, instrumentiert mit Checkpoints zur Kontrollfluss- und Lebendigkeitsüberwachung.</li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code>: Zentraler Systemdienst zur Überwachung von <em>Alive-</em>, <em>Deadline-</em> und <em>Logical Supervisions</em>.</li>\n<li><code>«aapFunctionalCluster» :Intrusion Detection System Manager</code>: Zentraler Plattformdienst zur Erfassung, Filterung und Weiterleitung von Security-Ereignissen (<em>Security Events</em>).</li>\n<li><strong>Operationen & Schnittstellen:</strong></li>\n<li><code>ReportCheckpoint()</code>: Interaktionsaufruf (IPC/API, i. d. R. <code>ara::phm</code>) von der Applikation an das PHM mit Übergabe der Checkpoint-ID.</li>\n<li><code>«aapInformative» checkAccess()</code>: PHM-interner Validierungsaufruf zur Prüfung der Prozess-Identität und Sendeberechtigung gegen die hinterlegte Zugriffs- bzw. Sicherheitskonfiguration (Identity & Access Management), explizit mit Stereotyp <code>«aapInformative»</code> als informativ gekennzeichnet.</li>\n<li><code>«aapInformative» handleReportedCheckpoint()</code>: PHM-interne Routine zur Aktualisierung der Überwachungsmodi (z. B. Hochzählen von Alive-Countern, Timer-Stopp/Start bei Deadlines, Graph-Traversierung bei Logical Supervisions), explizit mit Stereotyp <code>«aapInformative»</code> als informativ gekennzeichnet.</li>\n<li><code>ReportEvent()</code>: Standardisierte API-Interaktion (<code>ara::idsm</code>) zur Übergabe eines definierten Security Events (SEv) an den IdsM bei unautorisiertem Zugriff.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Die <code>:Adaptive Application</code> erreicht im Kontrollfluss einen Messpunkt und ruft synchron/asynchron <code>ReportCheckpoint()</code> auf dem <code>:Platform Health Management</code> auf.</li>\n<li><strong>Autorisierungsprüfung:</strong> PHM führt unverzüglich die interne Routine <code>checkAccess()</code> aus, um zu verifizieren, ob der aufrufende Kontext (Prozess/UID/PID) für diese spezifische Checkpoint-ID autorisiert ist.</li>\n<li><strong>Bedingte Verzweigung (<code>alt</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>[access granted]</code>:</strong> Bei erfolgreicher Autorisierung ruft PHM intern <code>handleReportedCheckpoint()</code> auf. Der Status der zugeordneten Supervisions (Alive/Deadline/Logical) wird aktualisiert; keine Benachrichtigung externer Security-Cluster.</li>\n<li><strong>Pfad <code>[access denied]</code>:</strong> Ist der Prozess nicht autorisiert (z. B. Prozess-Spoofing, korrumpierter Kontext), bricht PHM die Checkpoint-Auswertung ab und meldet den Vorfall via <code>ReportEvent()</code> an den <code>:Intrusion Detection System Manager</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest- & Konfigurationspflichten:</strong></li>\n<li>Checkpoints müssen im ARXML-Datenmodell (<code>HealthChannelAction</code>, <code>SupervisedEntity</code>, <code>Checkpoint</code>) modelliert und eindeutig einer Applikation bzw. einem Executable zugeordnet sein.</li>\n<li>Berechtigungen müssen in den Zugriffsregeln (IAM/Security Profiles) des PHM gepflegt sein; Diskrepanzen zwischen Applikationscode und Manifest führen unmittelbar zu <code>access denied</code>.</li>\n<li><strong>Einfluss auf die Applikationsentwicklung:</strong></li>\n<li>Applikationen dürfen Checkpoint-IDs nicht generisch oder dynamisch wählen; unzulässige oder nicht zugeordnete IDs provozieren Security-Meldungen im System.</li>\n<li>Instrumentierung mit <code>ReportCheckpoint()</code> muss strikt deterministisch erfolgen, um Timing- und Kontrollflussfehler zu vermeiden.</li>\n<li><strong>Einfluss auf Plattform-/Stack-Entwickler:</strong></li>\n<li>Das PHM muss eine performante Prozessauthentifizierung bereitstellen (z. B. via Peer-Credentials über Unix Domain Sockets), damit <code>checkAccess()</code> minimalen Overhead auf die Echtzeitausführung hat.</li>\n<li>Für den IdsM muss eine dedizierte <em>Security Event Definition</em> (SEv) für fehlgeschlagene Checkpoint-Zugriffe parametriert sein, inklusive Context-Data-Payload (z. B. fehlerhafte ID, anfragende Prozess-ID).</li>\n</ul>"}], "trans": [{"from": "FIG-8ba88db5c3893244", "to": "FIG-0aaa2ebc8b17d424", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Interne Methode <code>checkAccess()</code>:</strong> Ergänzung des Stereotyps <code>«aapInformative»</code> über dem Methodenaufruf auf der Lebenslinie <code>:Platform Health Management</code>.</li>\n<li><strong>Interne Methode <code>handleReportedCheckpoint()</code>:</strong> Ergänzung des Stereotyps <code>«aapInformative»</code> über dem Methodenaufruf auf der Lebenslinie <code>:Platform Health Management</code> innerhalb des <code>[access granted]</code>-Zweigs.</li>\n</ul>"}]};
